import SwiftUI

@main
@MainActor
struct CoroApp: App {
    @StateObject private var auth: SpotifyAuth
    @StateObject private var session: SessionController

    init() {
        let access = SpotifyAuth()
        _auth = StateObject(wrappedValue: access)
        _session = StateObject(wrappedValue: SessionController(auth: access))
    }

    var body: some Scene {
        WindowGroup {
            MainView(session: session, auth: auth)
                .preferredColorScheme(.dark)
                .tint(CoroStyle.accent)
        }
    }
}

import AVFoundation
import Foundation

/// Personal sideload-only experiment, not an App Store background mode claim.
/// A short silent PCM file loops locally; it is mixed with Spotify and does not
/// set Now Playing information, request a microphone, or control Spotify playback.
@MainActor
final class BackgroundAudio {
    private var player: AVAudioPlayer?

    func start() throws {
        guard let url = Bundle.main.url(forResource: "silence", withExtension: "wav") else {
            throw CoroError.message("Falta un recurso de la app. Es necesario recompilar Coro.")
        }
        let audio = AVAudioSession.sharedInstance()
        try audio.setCategory(.playback, mode: .default, options: [.mixWithOthers])
        try audio.setActive(true)
        do {
            let localPlayer = try AVAudioPlayer(contentsOf: url)
            localPlayer.numberOfLoops = -1
            localPlayer.prepareToPlay()
            guard localPlayer.play() else { throw CoroError.message("iOS no permitió mantener la sesión activa.") }
            player = localPlayer
        } catch {
            try? audio.setActive(false, options: [.notifyOthersOnDeactivation])
            throw error
        }
    }

    func stop() {
        guard player != nil else { return }
        player?.stop()
        player = nil
        try? AVAudioSession.sharedInstance().setActive(false, options: [.notifyOthersOnDeactivation])
    }
}

import Foundation
import Security

struct SpotifyCredentials: Codable {
    let accessToken: String
    let refreshToken: String
    let expiresAt: Date
}

enum KeychainStore {
    private static var query: [String: Any] {
        [kSecClass as String: kSecClassGenericPassword,
         kSecAttrService as String: "Coro.Spotify",
         kSecAttrAccount as String: "oauth"]
    }
    static func load() -> SpotifyCredentials? {
        var request = query
        request[kSecReturnData as String] = true
        request[kSecMatchLimit as String] = kSecMatchLimitOne
        var item: CFTypeRef?
        guard SecItemCopyMatching(request as CFDictionary, &item) == errSecSuccess,
              let data = item as? Data else { return nil }
        return try? JSONDecoder().decode(SpotifyCredentials.self, from: data)
    }
    static func save(_ credentials: SpotifyCredentials) throws {
        let data = try JSONEncoder().encode(credentials)
        let update = [kSecValueData as String: data,
                      kSecAttrAccessible as String: kSecAttrAccessibleAfterFirstUnlockThisDeviceOnly] as [String: Any]
        let status = SecItemUpdate(query as CFDictionary, update as CFDictionary)
        if status == errSecItemNotFound {
            var add = query
            update.forEach { add[$0.key] = $0.value }
            guard SecItemAdd(add as CFDictionary, nil) == errSecSuccess else { throw CoroError.message("No se pudo guardar el acceso de Spotify en este iPhone.") }
        } else if status != errSecSuccess {
            throw CoroError.message("No se pudo actualizar el acceso guardado de Spotify.")
        }
    }
    static func clear() { SecItemDelete(query as CFDictionary) }
}

import Foundation
import ActivityKit

@MainActor
final class LiveActivityController {
    private var activity: Activity<CoroAttributes>?
    private var previous: CoroAttributes.ContentState?
    private var lastUpdate = Date.distantPast
    private var stateTask: Task<Void, Never>?
    var onDismiss: (() -> Void)?

    func start(demo: Bool) async throws {
        guard ActivityAuthorizationInfo().areActivitiesEnabled else {
            throw CoroError.message("Activa las Actividades en vivo de Coro en Ajustes del iPhone.")
        }
        // Clean up activities left by a force quit or a previous installation.
        for old in Activity<CoroAttributes>.activities {
            await old.end(nil, dismissalPolicy: .immediate)
        }
        let initial = CoroAttributes.ContentState(title: demo ? "Demostración" : "Coro", artist: "",
                                                  line: "Preparando letras…", nextLine: "", notice: "",
                                                  isPlaying: false, isDemo: demo)
        activity = try Activity.request(attributes: CoroAttributes(sessionID: UUID()),
                                        content: ActivityContent(state: initial, staleDate: Date().addingTimeInterval(20)),
                                        pushType: nil)
        stateTask?.cancel()
        if let activity {
            stateTask = Task { [weak self] in
                for await state in activity.activityStateUpdates {
                    guard !Task.isCancelled, let self, self.activity?.id == activity.id else { return }
                    if state == .dismissed || state == .ended {
                        self.onDismiss?()
                        return
                    }
                }
            }
        }
        previous = initial
        lastUpdate = Date()
    }

    func update(_ state: CoroAttributes.ContentState, confirmedAt: Date?) async {
        guard let activity else { return }
        let fitted = Self.fit(state)
        guard fitted != previous || Date().timeIntervalSince(lastUpdate) >= 10 else { return }
        // The stale date always reflects real Spotify confirmation, not our local timer.
        let expires = (confirmedAt ?? Date()).addingTimeInterval(20)
        await activity.update(ActivityContent(state: fitted, staleDate: expires))
        previous = fitted
        lastUpdate = Date()
    }

    private static func fit(_ state: CoroAttributes.ContentState) -> CoroAttributes.ContentState {
        var value = state
        // ActivityKit permits 4 KB total; leave room for attributes and wrappers.
        // Measure encoded bytes because Unicode graphemes and JSON escaping vary.
        while ((try? JSONEncoder().encode(value).count) ?? Int.max) > 3400 {
            if !value.nextLine.isEmpty { value.nextLine = "" }
            else if !value.artist.isEmpty { value.artist = "" }
            else if !value.notice.isEmpty { value.notice = "" }
            else if value.title != "Coro" { value.title = "Coro" }
            else if !value.line.isEmpty { value.line = String(value.line.prefix(value.line.count / 2)) }
            else { break }
        }
        return value
    }

    func stop() {
        let old = activity
        activity = nil
        stateTask?.cancel()
        stateTask = nil
        previous = nil
        if let old { Task { await old.end(nil, dismissalPolicy: .immediate) } }
    }
}

import Foundation
import Network

/// OAuth callback bound exclusively to this iPhone's loopback interface.
/// The Safari sheet remains in the foreground while authorizing.
@MainActor
final class LoopbackCallback {
    static let redirect = "http://127.0.0.1:43821/callback"
    private var listener: NWListener?
    private var callback: ((URL) -> Void)?
    private var connections: [NWConnection] = []

    func start(callback: @escaping (URL) -> Void) async throws {
        stop()
        self.callback = callback
        let parameters = NWParameters.tcp
        parameters.requiredLocalEndpoint = .hostPort(host: "127.0.0.1", port: 43821)
        let server = try NWListener(using: parameters)
        listener = server
        server.newConnectionHandler = { [weak self] connection in
            Task { @MainActor in
                guard let self, self.listener != nil else { connection.cancel(); return }
                guard self.connections.count < 8 else { connection.cancel(); return }
                self.connections.append(connection)
                connection.start(queue: .main)
                self.receive(connection, buffer: Data())
                Task { @MainActor [weak self] in
                    try? await Task.sleep(nanoseconds: 10_000_000_000)
                    self?.close(connection)
                }
            }
        }
        try await withCheckedThrowingContinuation { (continuation: CheckedContinuation<Void, Error>) in
            var completed = false
            server.stateUpdateHandler = { state in
                guard !completed else { return }
                switch state {
                case .ready:
                    completed = true
                    continuation.resume()
                case .failed(let error):
                    completed = true
                    continuation.resume(throwing: error)
                case .cancelled:
                    completed = true
                    continuation.resume(throwing: CancellationError())
                default: break
                }
            }
            server.start(queue: .main)
        }
    }

    private func receive(_ connection: NWConnection, buffer: Data) {
        connection.receive(minimumIncompleteLength: 1, maximumLength: 4096) { [weak self] data, _, complete, error in
            Task { @MainActor in
                guard let self else { connection.cancel(); return }
                var collected = buffer
                if let data { collected.append(data) }
                guard error == nil, collected.count < 8192 else { self.close(connection); return }
                guard let request = String(data: collected, encoding: .utf8), request.contains("\r\n\r\n") else {
                    if complete { self.close(connection) } else { self.receive(connection, buffer: collected) }
                    return
                }
                let parts = request.components(separatedBy: "\r\n").first?.components(separatedBy: " ") ?? []
                guard parts.count == 3, parts[0] == "GET", parts[1].hasPrefix("/callback?"),
                      let url = URL(string: "http://127.0.0.1:43821" + parts[1]), url.path == "/callback" else {
                    self.reply(connection, status: "404 Not Found", message: "No disponible.")
                    return
                }
                self.reply(connection, status: "200 OK", message: "Puedes volver a Coro. Esta ventana se cerrara al terminar la conexion.") { [weak self] in
                    self?.callback?(url)
                }
            }
        }
    }

    private func reply(_ connection: NWConnection, status: String, message: String, completion: (() -> Void)? = nil) {
        let body = Data(message.utf8)
        let header = "HTTP/1.1 \(status)\r\nContent-Type: text/plain; charset=utf-8\r\nCache-Control: no-store\r\nPragma: no-cache\r\nReferrer-Policy: no-referrer\r\nConnection: close\r\nContent-Length: \(body.count)\r\n\r\n"
        connection.send(content: Data(header.utf8) + body, completion: .contentProcessed { [weak self] _ in
            Task { @MainActor in
                self?.close(connection)
                completion?()
            }
        })
    }

    private func close(_ connection: NWConnection) {
        connection.cancel()
        connections.removeAll { $0 === connection }
    }

    func stop() {
        listener?.cancel()
        listener = nil
        connections.forEach { $0.cancel() }
        connections.removeAll()
        callback = nil
    }
}

import Foundation
import LyricsCore

struct LyricsResult: Sendable {
    let lines: [LyricLine]
    let notice: String
}

actor LyricsClient {
    private var cache: [String: LyricsResult] = [:]
    private var cacheOrder: [String] = []
    private var allowedAfter = Date.distantPast

    func get(for track: Track) async throws -> LyricsResult {
        if let stored = cache[track.id] { return stored }
        guard track.duration > 0, track.duration <= 3600 else {
            return LyricsResult(lines: [], notice: "No hay letra disponible para esta pista.")
        }
        let artist = track.artists.first ?? ""
        let query: [URLQueryItem] = [
            .init(name: "track_name", value: track.title),
            .init(name: "artist_name", value: artist),
            .init(name: "album_name", value: track.album),
            .init(name: "duration", value: String(Int(track.duration.rounded())))
        ]
        var result: LyricsRecord?
        if let data = try await fetch(path: "/api/get", items: query) {
            result = try JSONDecoder().decode(LyricsRecord.self, from: data)
        }
        // If the exact signature has no synchronized version, consider only
        // matching title, artist and duration. Never invent timing for plain text.
        if result?.syncedLyrics == nil, result?.instrumental != true {
            try await Task.sleep(nanoseconds: 300_000_000)
            if let data = try await fetch(path: "/api/search", items: [
                .init(name: "track_name", value: track.title), .init(name: "artist_name", value: artist)
            ]) {
                let records = try JSONDecoder().decode([LyricsRecord].self, from: data)
                if let alternative = LyricsMatcher.best(in: records, for: track) { result = alternative }
            }
        }
        try Task.checkCancellation()
        let lines = LRCParser.parse(result?.syncedLyrics ?? "")
        let notice: String
        if result?.instrumental == true { notice = "Pista instrumental" }
        else if lines.isEmpty { notice = "Esta canción no tiene letra sincronizada en LRCLIB." }
        else { notice = "" }
        let resolved = LyricsResult(lines: lines, notice: notice)
        cache[track.id] = resolved
        cacheOrder.removeAll { $0 == track.id }
        cacheOrder.append(track.id)
        while cacheOrder.count > 80 { cache.removeValue(forKey: cacheOrder.removeFirst()) }
        return resolved
    }

    private func fetch(path: String, items: [URLQueryItem]) async throws -> Data? {
        if allowedAfter > Date() {
            try await Task.sleep(nanoseconds: UInt64(min(allowedAfter.timeIntervalSinceNow, 3600) * 1_000_000_000))
            if allowedAfter > Date() { throw CoroError.rateLimited(allowedAfter.timeIntervalSinceNow) }
        }
        try Task.checkCancellation()
        var url = URLComponents(string: "https://lrclib.net" + path)!
        url.queryItems = items
        var request = URLRequest(url: url.url!)
        let projectURL = Bundle.main.object(forInfoDictionaryKey: "CoroProjectURL") as? String ?? ""
        let identification = projectURL.isEmpty ? "Coro/0.1 personal lyrics companion" : "Coro/0.1 (\(projectURL))"
        request.setValue(identification, forHTTPHeaderField: "User-Agent")
        request.setValue("application/json", forHTTPHeaderField: "Accept")
        do {
            let (data, response) = try await Network.request(request)
            if response.statusCode == 404 { return nil }
            guard response.statusCode == 200, data.count <= 2_000_000 else {
                throw CoroError.message("No se pudo consultar la letra (\(response.statusCode)).")
            }
            return data
        } catch CoroError.rateLimited(let seconds) {
            let wait = seconds + Double.random(in: 0...max(0.1, min(5, seconds * 0.2)))
            allowedAfter = Date().addingTimeInterval(wait)
            throw CoroError.rateLimited(wait)
        }
    }

    func clear() { cache.removeAll(); cacheOrder.removeAll() }
}

import Foundation
import LyricsCore

enum CoroError: LocalizedError {
    case message(String)
    case rateLimited(TimeInterval)
    case unauthorized
    var errorDescription: String? {
        switch self {
        case .message(let text): return text
        case .rateLimited: return "El servicio pide una pausa. Coro reintentará automáticamente."
        case .unauthorized: return "Vuelve a conectar Spotify."
        }
    }
}

enum Network {
    static let session: URLSession = {
        let config = URLSessionConfiguration.ephemeral
        config.timeoutIntervalForRequest = 12
        config.timeoutIntervalForResource = 20
        config.waitsForConnectivity = false
        config.urlCache = nil
        return URLSession(configuration: config)
    }()

    static func request(_ request: URLRequest) async throws -> (Data, HTTPURLResponse) {
        let (data, response) = try await session.data(for: request)
        guard let http = response as? HTTPURLResponse else { throw CoroError.message("Respuesta de red no válida.") }
        if http.statusCode == 429 || http.statusCode == 503 {
            throw CoroError.rateLimited(RetryDelay.seconds(from: http.value(forHTTPHeaderField: "Retry-After")))
        }
        return (data, http)
    }

    static func form(_ values: [String: String]) -> Data {
        let allowed = CharacterSet.alphanumerics.union(CharacterSet(charactersIn: "-._~"))
        return Data(values.sorted { $0.key < $1.key }.map {
            "\($0.key.addingPercentEncoding(withAllowedCharacters: allowed)!)=\($0.value.addingPercentEncoding(withAllowedCharacters: allowed)!)"
        }.joined(separator: "&").utf8)
    }
}

import Foundation
import Combine
import CryptoKit
import Security

struct AuthorizationPage: Identifiable {
    let id = UUID()
    let url: URL
}

@MainActor
final class SpotifyAuth: ObservableObject {
    @Published private(set) var clientID: String
    @Published private(set) var isConnected = false
    @Published private(set) var isAuthorizing = false
    @Published var page: AuthorizationPage?
    @Published var message: String?
    private var credentials: SpotifyCredentials?
    private var pending: (verifier: String, state: String)?
    private let callbackServer = LoopbackCallback()
    private var timeout: Task<Void, Never>?
    private var refresh: Task<String, Error>?
    private var generation = 0

    init() {
        clientID = UserDefaults.standard.string(forKey: "spotifyClientID") ?? ""
        credentials = KeychainStore.load()
        isConnected = credentials != nil && !clientID.isEmpty
    }

    func configure(clientID: String) throws {
        let value = clientID.trimmingCharacters(in: .whitespacesAndNewlines)
        guard value.range(of: "^[a-fA-F0-9]{32}$", options: .regularExpression) != nil else {
            throw CoroError.message("El Client ID debe tener 32 caracteres. No pegues el Client Secret ni tu contraseña.")
        }
        if value != self.clientID { disconnect() }
        self.clientID = value
        UserDefaults.standard.set(value, forKey: "spotifyClientID")
    }

    func connect() async {
        guard !isAuthorizing else { return }
        guard !clientID.isEmpty else { message = "Primero añade el Client ID en Ajustes."; return }
        isAuthorizing = true
        generation += 1
        message = nil
        do {
            let verifier = try Self.randomString()
            let state = try Self.randomString()
            pending = (verifier, state)
            try await callbackServer.start { [weak self] url in
                Task { @MainActor in await self?.finish(url) }
            }
            let challenge = Self.base64URL(Data(SHA256.hash(data: Data(verifier.utf8))))
            var url = URLComponents(string: "https://accounts.spotify.com/authorize")!
            url.queryItems = [
                .init(name: "client_id", value: clientID),
                .init(name: "response_type", value: "code"),
                .init(name: "redirect_uri", value: LoopbackCallback.redirect),
                .init(name: "scope", value: "user-read-currently-playing"),
                .init(name: "code_challenge_method", value: "S256"),
                .init(name: "code_challenge", value: challenge),
                .init(name: "state", value: state)
            ]
            page = AuthorizationPage(url: url.url!)
            timeout = Task { [weak self] in
                do { try await Task.sleep(nanoseconds: 300_000_000_000) } catch { return }
                guard let self, self.pending != nil else { return }
                self.cancelLogin()
                self.message = "La conexión tardó demasiado. Inténtalo otra vez."
            }
        } catch {
            cancelLogin()
            message = "No se pudo iniciar la conexión: \(error.localizedDescription)"
        }
    }

    private func finish(_ url: URL) async {
        guard let flow = pending else { return }
        let operation = generation
        let items = URLComponents(url: url, resolvingAgainstBaseURL: false)?.queryItems ?? []
        guard items.filter({ $0.name == "state" }).count == 1,
              items.first(where: { $0.name == "state" })?.value == flow.state else {
            message = "Se rechazó una respuesta de acceso no válida."
            return
        }
        timeout?.cancel()
        pending = nil
        page = nil
        callbackServer.stop()
        defer { if generation == operation { isAuthorizing = false } }
        if items.contains(where: { $0.name == "error" }) {
            message = "Spotify no autorizó el acceso. Puedes intentarlo de nuevo."
            return
        }
        guard items.filter({ $0.name == "code" }).count == 1,
              let code = items.first(where: { $0.name == "code" })?.value, !code.isEmpty else {
            message = "Spotify devolvió una respuesta incompleta."
            return
        }
        do {
            let response = try await tokenRequest([
                "client_id": clientID, "grant_type": "authorization_code", "code": code,
                "redirect_uri": LoopbackCallback.redirect, "code_verifier": flow.verifier
            ])
            guard generation == operation else { return }
            guard let refreshToken = response.refresh_token, !refreshToken.isEmpty else { throw CoroError.unauthorized }
            try store(response, refreshToken: refreshToken)
            message = "Spotify conectado."
        } catch { if generation == operation { message = error.localizedDescription } }
    }

    func dismissAuthorization() {
        if pending != nil { cancelLogin() }
    }

    func cancelLogin() {
        timeout?.cancel()
        timeout = nil
        callbackServer.stop()
        pending = nil
        page = nil
        isAuthorizing = false
    }

    func disconnect() {
        generation += 1
        cancelLogin()
        refresh?.cancel()
        refresh = nil
        KeychainStore.clear()
        credentials = nil
        isConnected = false
        message = nil
    }

    func accessToken(forceRefresh: Bool = false) async throws -> String {
        guard let existing = credentials else { throw CoroError.unauthorized }
        if !forceRefresh, existing.expiresAt.timeIntervalSinceNow > 60 { return existing.accessToken }
        if let refresh { return try await refresh.value }
        let task = Task<String, Error> { [weak self] in
            guard let self else { throw CoroError.unauthorized }
            let result = try await self.tokenRequest([
                "client_id": self.clientID, "grant_type": "refresh_token", "refresh_token": existing.refreshToken
            ])
            try Task.checkCancellation()
            try self.store(result, refreshToken: result.refresh_token ?? existing.refreshToken)
            return result.access_token
        }
        refresh = task
        defer { refresh = nil }
        return try await task.value
    }

    private struct TokenResponse: Decodable {
        let access_token: String
        let expires_in: Double
        let refresh_token: String?
    }

    private func tokenRequest(_ fields: [String: String]) async throws -> TokenResponse {
        var request = URLRequest(url: URL(string: "https://accounts.spotify.com/api/token")!)
        request.httpMethod = "POST"
        request.setValue("application/x-www-form-urlencoded", forHTTPHeaderField: "Content-Type")
        request.httpBody = Network.form(fields)
        let (data, response) = try await Network.request(request)
        guard response.statusCode == 200 else {
            if response.statusCode == 400 || response.statusCode == 401 { throw CoroError.unauthorized }
            throw CoroError.message("Spotify no pudo completar el acceso (\(response.statusCode)).")
        }
        return try JSONDecoder().decode(TokenResponse.self, from: data)
    }

    private func store(_ response: TokenResponse, refreshToken: String) throws {
        let value = SpotifyCredentials(accessToken: response.access_token, refreshToken: refreshToken,
                                       expiresAt: Date().addingTimeInterval(response.expires_in))
        try KeychainStore.save(value)
        credentials = value
        isConnected = true
    }

    private static func randomString() throws -> String {
        var bytes = [UInt8](repeating: 0, count: 32)
        guard SecRandomCopyBytes(kSecRandomDefault, bytes.count, &bytes) == errSecSuccess else {
            throw CoroError.message("No se pudo preparar una conexión segura.")
        }
        return base64URL(Data(bytes))
    }
    private static func base64URL(_ data: Data) -> String {
        data.base64EncodedString().replacingOccurrences(of: "+", with: "-")
            .replacingOccurrences(of: "/", with: "_").replacingOccurrences(of: "=", with: "")
    }
}

import Foundation
import LyricsCore

struct SpotifySnapshot {
    let track: Track
    let anchor: PlaybackAnchor
    let confirmedAt: Date
}

@MainActor
final class SpotifyClient {
    let auth: SpotifyAuth
    init(auth: SpotifyAuth) { self.auth = auth }

    func current() async throws -> SpotifySnapshot? {
        var token = try await auth.accessToken()
        for attempt in 0..<2 {
            let start = ProcessInfo.processInfo.systemUptime
            var request = URLRequest(url: URL(string: "https://api.spotify.com/v1/me/player/currently-playing")!)
            request.setValue("Bearer \(token)", forHTTPHeaderField: "Authorization")
            let (data, response) = try await Network.request(request)
            let end = ProcessInfo.processInfo.systemUptime
            if response.statusCode == 401, attempt == 0 {
                token = try await auth.accessToken(forceRefresh: true)
                continue
            }
            if response.statusCode == 204 { return nil }
            if response.statusCode == 401 { throw CoroError.unauthorized }
            if response.statusCode == 403 {
                throw CoroError.message("Spotify denegó el acceso. Revisa Premium, el Client ID y los usuarios autorizados de tu app.")
            }
            guard response.statusCode == 200 else {
                throw CoroError.message("Spotify no responde por ahora (\(response.statusCode)).")
            }
            let value = try JSONDecoder().decode(PlaybackResponse.self, from: data)
            guard value.currently_playing_type == "track", let song = value.item,
                  song.type == "track", song.is_local != true, let id = song.id,
                  let progress = value.progress_ms else { return nil }
            let track = Track(id: id, title: song.name, artists: song.artists.map(\.name),
                              album: song.album.name, duration: Double(song.duration_ms) / 1000,
                              spotifyURL: song.external_urls?["spotify"].flatMap { URL(string: $0) })
            // The Web API's timestamp is not a continuously updated playback clock.
            // Anchor the returned progress to the request midpoint, then use monotonic time.
            return SpotifySnapshot(track: track,
                                   anchor: PlaybackAnchor(position: Double(progress) / 1000, duration: track.duration,
                                                          observedAt: (start + end) / 2, isPlaying: value.is_playing),
                                   confirmedAt: Date())
        }
        throw CoroError.unauthorized
    }

    private struct PlaybackResponse: Decodable {
        let is_playing: Bool
        let progress_ms: Int?
        let currently_playing_type: String
        let item: Item?
        private enum CodingKeys: String, CodingKey { case is_playing, progress_ms, currently_playing_type, item }
        init(from decoder: Decoder) throws {
            let values = try decoder.container(keyedBy: CodingKeys.self)
            is_playing = try values.decode(Bool.self, forKey: .is_playing)
            progress_ms = try values.decodeIfPresent(Int.self, forKey: .progress_ms)
            currently_playing_type = try values.decode(String.self, forKey: .currently_playing_type)
            if currently_playing_type == "track" {
                item = try values.decodeIfPresent(Item.self, forKey: .item)
            } else {
                item = nil
            }
        }
    }
    private struct Item: Decodable {
        let id: String?
        let type: String
