const sampleRate = 8000;
const seconds = 12;
const pcmSize = sampleRate * seconds * 2;
const wave = Buffer.alloc(44 + pcmSize);
wave.write('RIFF', 0);
wave.writeUInt32LE(36 + pcmSize, 4);
wave.write('WAVEfmt ', 8);
wave.writeUInt32LE(16, 16);
