import Foundation

public struct LyricLine: Codable, Equatable, Sendable {
    public let time: TimeInterval
    public let text: String
    public init(time: TimeInterval, text: String) {
        self.time = time
        self.text = text
    }
}

public enum LRCParser {
    /// Preserves timed empty lines: they mark instrumental breaks.
    /// LRC offsets are milliseconds. Positive offsets advance the text.
    public static func parse(_ input: String) -> [LyricLine] {
        let stamp = try! NSRegularExpression(pattern: #"\[(\d{1,3}):(\d{2})(?:[.:](\d{1,3}))?\]"#)
        let offsetPattern = try! NSRegularExpression(pattern: #"(?im)^\s*\[offset:([+-]?\d+)\]\s*$"#)
        let whole = input as NSString
        var offset: Double = 0
        if let match = offsetPattern.matches(in: input, range: NSRange(location: 0, length: whole.length)).last {
            offset = (Double(whole.substring(with: match.range(at: 1))) ?? 0) / 1000
        }
        var entries: [(line: LyricLine, order: Int)] = []
        for raw in input.components(separatedBy: .newlines) {
            let source = raw.trimmingCharacters(in: .whitespacesAndNewlines)
            let ns = source as NSString
            let matches = stamp.matches(in: source, range: NSRange(location: 0, length: ns.length))
            guard let last = matches.last, matches.first?.range.location == 0 else { continue }
            let text = ns.substring(from: NSMaxRange(last.range)).trimmingCharacters(in: .whitespaces)
            for match in matches {
                guard let minute = Double(ns.substring(with: match.range(at: 1))),
                      let second = Double(ns.substring(with: match.range(at: 2))), second < 60 else { continue }
                let fractionRange = match.range(at: 3)
                let fraction = fractionRange.location == NSNotFound ? 0 :
                    (Double("0." + ns.substring(with: fractionRange)) ?? 0)
                let time = max(0, minute * 60 + second + fraction - offset)
                entries.append((LyricLine(time: time, text: text), entries.count))
            }
        }
        entries.sort { $0.line.time == $1.line.time ? $0.order < $1.order : $0.line.time < $1.line.time }
        var result: [LyricLine] = []
        for entry in entries {
            if let previous = result.last, abs(previous.time - entry.line.time) < 0.00001 {
                if previous.text == entry.line.text { continue }
                // Two simultaneous voices / translations stay on the same line.
                let combined = [previous.text, entry.line.text].filter { !$0.isEmpty }.joined(separator: " · ")
                result[result.count - 1] = LyricLine(time: previous.time, text: combined)
            } else {
                result.append(entry.line)
            }
        }
        return result
    }

    public static func index(at position: TimeInterval, in lines: [LyricLine]) -> Int? {
        guard position.isFinite, let first = lines.first, position >= first.time else { return nil }
        var low = 0
        var high = lines.count
        while low < high {
            let middle = (low + high) / 2
            if lines[middle].time <= position { low = middle + 1 } else { high = middle }
        }
        return low - 1
    }
}

public struct PlaybackAnchor: Sendable {
    public let position: TimeInterval
    public let duration: TimeInterval
    public let observedAt: TimeInterval
    public let isPlaying: Bool
    public init(position: TimeInterval, duration: TimeInterval, observedAt: TimeInterval, isPlaying: Bool) {
        self.position = position
        self.duration = duration
        self.observedAt = observedAt
        self.isPlaying = isPlaying
    }
    public func position(at uptime: TimeInterval) -> TimeInterval {
        let elapsed = isPlaying ? max(0, uptime - observedAt) : 0
        return min(max(0, duration), max(0, position + elapsed))
    }
    public func isFresh(at uptime: TimeInterval, lifetime: TimeInterval = 20) -> Bool {
        uptime >= observedAt && uptime - observedAt <= lifetime
    }
}

public struct Track: Equatable, Sendable {
    public let id: String
    public let title: String
    public let artists: [String]
    public let album: String
    public let duration: TimeInterval
    public let spotifyURL: URL?
    public init(id: String, title: String, artists: [String], album: String, duration: TimeInterval, spotifyURL: URL?) {
        self.id = id
        self.title = title
        self.artists = artists
        self.album = album
        self.duration = duration
        self.spotifyURL = spotifyURL
    }
}

public struct LyricsRecord: Decodable, Sendable {
    public let id: Int
    public let trackName: String
    public let artistName: String
    public let duration: Double
    public let instrumental: Bool
    public let plainLyrics: String?
    public let syncedLyrics: String?
    public init(id: Int, trackName: String, artistName: String, duration: Double, instrumental: Bool,
                plainLyrics: String? = nil, syncedLyrics: String? = nil) {
        self.id = id; self.trackName = trackName; self.artistName = artistName
        self.duration = duration; self.instrumental = instrumental
        self.plainLyrics = plainLyrics; self.syncedLyrics = syncedLyrics
    }
}

public enum LyricsMatcher {
    public static func normalized(_ text: String) -> String {
        text.folding(options: [.diacriticInsensitive, .caseInsensitive], locale: Locale(identifier: "en_US_POSIX"))
            .components(separatedBy: CharacterSet.alphanumerics.inverted).filter { !$0.isEmpty }.joined(separator: " ")
    }
    public static func best(in records: [LyricsRecord], for track: Track) -> LyricsRecord? {
        let candidates = records.filter { record in
            abs(record.duration - track.duration) <= 2 && normalized(record.trackName) == normalized(track.title) &&
            track.artists.contains { normalized($0) == normalized(record.artistName) }
        }
        return candidates.sorted {
            let leftSynced = !($0.syncedLyrics ?? "").isEmpty
            let rightSynced = !($1.syncedLyrics ?? "").isEmpty
            if leftSynced != rightSynced { return leftSynced }
            return abs($0.duration - track.duration) < abs($1.duration - track.duration)
        }.first
    }
}

public enum RetryDelay {
    public static func seconds(from value: String?, now: Date = Date()) -> TimeInterval {
        guard let value else { return 30 }
        if let seconds = Double(value), seconds.isFinite { return max(1, seconds) }
        let formatter = DateFormatter()
        formatter.locale = Locale(identifier: "en_US_POSIX")
        formatter.timeZone = TimeZone(secondsFromGMT: 0)
        formatter.dateFormat = "EEE, dd MMM yyyy HH:mm:ss zzz"
        if let date = formatter.date(from: value) { return max(1, date.timeIntervalSince(now)) }
        return 30
    }
}

import XCTest
@testable import LyricsCore

final class LyricsCoreTests: XCTestCase {
    func testFractionsAndRepeatedTimestamps() {
        let lines = LRCParser.parse("[ar:Test]\n[00:01.5][00:03.125]Uno\n[00:02.50]Dos")
        XCTAssertEqual(lines.map(\.time), [1.5, 2.5, 3.125])
        XCTAssertEqual(lines.map(\.text), ["Uno", "Dos", "Uno"])
    }
    func testPositiveOffsetAdvancesLyrics() {
        XCTAssertEqual(LRCParser.parse("[offset:500]\n[00:02.00]Hola").first?.time, 1.5)
    }
    func testNegativeOffsetDelaysLyrics() {
        XCTAssertEqual(LRCParser.parse("[offset:-500]\n[00:02.00]Hola").first?.time, 2.5)
    }
    func testEmptyLineMarksInstrumentalBreak() {
        let lines = LRCParser.parse("[00:01]Voz\n[00:04]\n[00:06]Otra voz")
        XCTAssertEqual(lines[LRCParser.index(at: 5, in: lines)!].text, "")
    }
    func testInvalidTimestampIgnored() {
        XCTAssertEqual(LRCParser.parse("[00:72]Mal\n[ar:Una banda]\nSin tiempos"), [])
    }
    func testDuplicateAndSimultaneousLines() {
        let lines = LRCParser.parse("[00:01]Uno\n[00:01]Uno\n[00:01]Dos")
        XCTAssertEqual(lines, [LyricLine(time: 1, text: "Uno · Dos")])
    }
    func testSeekAndExactBoundary() {
        let lines = LRCParser.parse("[00:02]A\n[00:05]B\n[00:08]C")
        XCTAssertNil(LRCParser.index(at: 1.9, in: lines))
        XCTAssertEqual(LRCParser.index(at: 8, in: lines), 2)
        XCTAssertEqual(LRCParser.index(at: 3, in: lines), 0)
        XCTAssertEqual(LRCParser.index(at: 5, in: lines), 1)
        XCTAssertNil(LRCParser.index(at: .nan, in: lines))
    }
    func testPausedPlaybackDoesNotAdvance() {
        let anchor = PlaybackAnchor(position: 12, duration: 30, observedAt: 100, isPlaying: false)
        XCTAssertEqual(anchor.position(at: 110), 12)
    }
    func testPlaybackClampsAtEnd() {
        let anchor = PlaybackAnchor(position: 29, duration: 30, observedAt: 100, isPlaying: true)
        XCTAssertEqual(anchor.position(at: 120), 30)
    }
    func testStalePlaybackIsNotTreatedAsLive() {
        let anchor = PlaybackAnchor(position: 10, duration: 30, observedAt: 100, isPlaying: true)
        XCTAssertTrue(anchor.isFresh(at: 120))
        XCTAssertFalse(anchor.isFresh(at: 120.1))
        XCTAssertFalse(anchor.isFresh(at: 99))
    }
    func testNegativePositionClamped() {
        XCTAssertEqual(PlaybackAnchor(position: -5, duration: 20, observedAt: 10, isPlaying: false).position(at: 12), 0)
    }
    func testMatchingRejectsAnotherVersionAndArtist() {
        let track = Track(id: "demo", title: "Canción", artists: ["Autor"], album: "Álbum", duration: 180, spotifyURL: nil)
        let wrong = [
            LyricsRecord(id: 1, trackName: "Canción (Live)", artistName: "Autor", duration: 180, instrumental: false),
            LyricsRecord(id: 2, trackName: "Canción", artistName: "Otro", duration: 180, instrumental: false),
            LyricsRecord(id: 3, trackName: "Canción", artistName: "Autor", duration: 190, instrumental: false)
        ]
        XCTAssertNil(LyricsMatcher.best(in: wrong, for: track))
        let match = LyricsRecord(id: 4, trackName: "cancion", artistName: "AUTOR", duration: 181, instrumental: false, syncedLyrics: "[00:01]Sí")
        XCTAssertEqual(LyricsMatcher.best(in: wrong + [match], for: track)?.id, 4)
    }
    func testSyncedVersionPreferred() {
        let track = Track(id: "a", title: "A", artists: ["B"], album: "C", duration: 180, spotifyURL: nil)
        let plain = LyricsRecord(id: 1, trackName: "A", artistName: "B", duration: 180, instrumental: false, plainLyrics: "A")
        let timed = LyricsRecord(id: 2, trackName: "A", artistName: "B", duration: 181, instrumental: false, syncedLyrics: "[00:01]A")
        XCTAssertEqual(LyricsMatcher.best(in: [plain, timed], for: track)?.id, 2)
    }
    func testRetryAfterSecondsAndDate() {
        XCTAssertEqual(RetryDelay.seconds(from: "120"), 120)
        XCTAssertEqual(RetryDelay.seconds(from: "-1"), 1)
        XCTAssertEqual(RetryDelay.seconds(from: nil), 30)
        XCTAssertEqual(RetryDelay.seconds(from: "n/a"), 30)
        XCTAssertEqual(RetryDelay.seconds(from: "Thu, 01 Jan 1970 00:01:00 GMT", now: Date(timeIntervalSince1970: 0)), 60)
    }
}

import SwiftUI
import WidgetKit
import ActivityKit

@main
struct CoroWidgetBundle: WidgetBundle {
    var body: some Widget { CoroLiveActivity() }
}

struct CoroLiveActivity: Widget {
    var body: some WidgetConfiguration {
        ActivityConfiguration(for: CoroAttributes.self) { context in
            LyricsCard(context: context)
                .activityBackgroundTint(.black)
                .activitySystemActionForegroundColor(.white)
        } dynamicIsland: { context in
            DynamicIsland {
                DynamicIslandExpandedRegion(.leading) {
                    Label(context.state.isDemo ? "DEMO" : "Coro", systemImage: "music.note")
                        .font(.caption.weight(.semibold)).foregroundStyle(.orange)
                }
                DynamicIslandExpandedRegion(.trailing) {
                    Image(systemName: context.state.isPlaying ? "waveform" : "pause.fill")
                }
                DynamicIslandExpandedRegion(.bottom) {
                    VStack(alignment: .leading, spacing: 5) {
                        Text(context.isStale ? "Esperando a Spotify…" : context.state.line)
                            .font(.headline).lineLimit(2)
                        if !context.isStale {
                            Text(context.state.nextLine).font(.caption).foregroundStyle(.secondary).lineLimit(1)
                        }
                    }
                }
            } compactLeading: {
                Image(systemName: "music.note").foregroundStyle(.orange)
            } compactTrailing: {
                Text(context.isStale ? "…" : (context.state.isDemo ? "DEMO" : "Coro")).font(.caption2)
            } minimal: {
                Image(systemName: "music.note").foregroundStyle(.orange)
            }
            .keylineTint(.orange)
        }
        .supplementalActivityFamilies([.small, .medium])
    }
}

struct LyricsCard: View {
    @Environment(\.activityFamily) private var family
    let context: ActivityViewContext<CoroAttributes>
    private let coral = Color(red: 1, green: 0.52, blue: 0.39)

    var body: some View {
        VStack(alignment: .leading, spacing: family == .small ? 5 : 8) {
            HStack(spacing: 5) {
                Image(systemName: "music.note").foregroundStyle(coral)
                Text(context.state.isDemo ? "DEMO" : context.state.title).lineLimit(1)
                Spacer(minLength: 0)
                if !context.state.isPlaying { Image(systemName: "pause.fill") }
            }
            .font(.caption2.weight(.semibold)).foregroundStyle(.white.opacity(0.65))
            Text(context.isStale ? "Esperando a Spotify…" : context.state.line)
                .font(family == .small ? .system(size: 18, weight: .bold, design: .rounded) : .title3.weight(.semibold))
                .foregroundStyle(coral)
                .lineLimit(2)
                .minimumScaleFactor(0.8)
                .frame(maxWidth: .infinity, alignment: .leading)
            if !context.isStale, !context.state.nextLine.isEmpty {
                Text(context.state.nextLine)
                    .font(family == .small ? .caption2 : .subheadline)
                    .foregroundStyle(.white.opacity(0.6)).lineLimit(1)
            }
            if family != .small, !context.state.notice.isEmpty {
                Text(context.state.notice).font(.caption2).foregroundStyle(.white.opacity(0.5)).lineLimit(1)
            }
        }
        .padding(family == .small ? 9 : 16)
    }
}
